/**
 * Compositional finite-work proof for the closed evaluator.  This is deliberately
 * a compiler proof, not a second interpreter or a fuel counter: it follows the
 * same executable-node boundary as core-types and assigns a finite transfer bound
 * to every operator arm.  The graph combines the transfers with its checked DAG,
 * finite dynamic-demand depth, bounded row expansion, and captured-input envelope.
 */
import { deriveCoreTypes } from './core-types.js'
import type { RuleEngineLimits } from './limits.js'
import { cell, type Json, type RuleDefinition } from './model.js'

const INPUT_BYTES = 262_144n
const INPUT_NODES = 5_000n
const MONEY_DIGITS = 4_096n
const MONEY_SCALE = 4_096n
const NUMBER_BYTES = 32n
// Two parsed operands can each carry 4096 digits.  Alignment can append at
// most 4096 zeroes to one mantissa; a sum/subtract can carry one more digit.
// Canonical decimal text additionally has sign, point and JSON quotes.
const MONEY_ADD_RESULT_BYTES = (MONEY_DIGITS + MONEY_SCALE + 1n) + 4n
const MONEY_MUL_RESULT_BYTES = MONEY_DIGITS + 4n

export interface WorkProof {
  /** Largest serialized result admitted by the proof; metadata only, never authored JSON. */
  maximumResultBytes: bigint
  /** Structural copying/conversion/comparison/fold work for one bounded graph generation. */
  maximumEvaluationWork: bigint
}

interface NodeProof {
  result: bigint
  work: bigint
  reads: bigint
  aggregateReads: bigint
}

const max = (...values: bigint[]): bigint => values.reduce((a, b) => a > b ? a : b, 0n)
const sum = (values: readonly bigint[]): bigint => values.reduce((a, b) => a + b, 0n)
const add = (...values: bigint[]): bigint => sum(values)
const isObject = (value: Json): value is Record<string, Json> => value !== null && typeof value === 'object' && !Array.isArray(value)

// JSON text can escape each UTF-16 code unit as \uXXXX.  This deliberately
// over-bounds UTF-8/escaping without allocating a second serialized expression.
function literalBytes(value: Json): bigint {
  if (value === null) return 4n
  if (typeof value === 'boolean') return value ? 4n : 5n
  if (typeof value === 'number') return NUMBER_BYTES
  if (typeof value === 'string') return 2n + 6n * BigInt(value.length)
  if (Array.isArray(value)) return 2n + sum(value.map(literalBytes)) + BigInt(Math.max(0, value.length - 1))
  return 2n + sum(Object.entries(value).map(([key, child]) => 2n + 6n * BigInt(key.length) + 1n + literalBytes(child)))
    + BigInt(Math.max(0, Object.keys(value).length - 1))
}

function inertProof(value: Json): NodeProof {
  const bytes = literalBytes(value)
  return { result: bytes, work: add(1n, bytes), reads: 0n, aggregateReads: 0n }
}

function merge(children: readonly NodeProof[]): Pick<NodeProof, 'work' | 'reads' | 'aggregateReads'> {
  return {
    work: sum(children.map(child => child.work)),
    reads: sum(children.map(child => child.reads)),
    aggregateReads: sum(children.map(child => child.aggregateReads)),
  }
}

// `cat` converts JSON values to text and returns a JSON string.  A source JSON
// byte can become a UTF-16 code unit and be escaped again (six bytes), plus the
// enclosing quotes.  This covers nested literal containers and quoted strings.
function catStringResultBytes(value: bigint): bigint { return 2n + 6n * value }

function staticVarPath(raw: Json): string | null {
  const path = Array.isArray(raw) ? raw[0] : raw
  return typeof path === 'string' ? path : null
}

function deriveNode(node: Json, dependencyResult: bigint, aggregateResult: bigint,
  staticReference?: (path: string) => bigint | undefined): NodeProof {
  // The evaluator regards arrays and multi-key objects as literal JSON data.
  if (!isObject(node) || Object.keys(node).length !== 1) return inertProof(node)
  const [op, raw] = Object.entries(node)[0]
  const args = Array.isArray(raw) ? raw : [raw]
  const children = args.map(arg => deriveNode(arg, dependencyResult, aggregateResult, staticReference))
  const child = merge(children)
  const childResult = max(...children.map(item => item.result))
  const childBytes = sum(children.map(item => item.result))
  const base = (result: bigint, transfer: bigint, reads = child.reads, aggregateReads = child.aggregateReads): NodeProof => ({
    result,
    work: add(1n, child.work, transfer),
    reads,
    aggregateReads,
  })

  switch (op) {
    case 'var':
      // The fallback is eager in both tiers.  The resolver lookup is explicit work.
      { const path = staticVarPath(raw)
        const resolved = path === null ? dependencyResult : staticReference?.(path) ?? INPUT_BYTES
        return base(max(resolved, childResult), add(childBytes, 1n), child.reads + 1n) }
    case 'missing': {
      // One non-array operand is evaluated once for the array test and again to make
      // the key list.  Every discovered key performs a resolver lookup.
      const keyCount = args.length === 1 ? INPUT_NODES : BigInt(args.length)
      const firstTwice = args.length === 1 ? children[0]?.work ?? 0n : 0n
      const keyBytes = max(childResult, 1n)
      return {
        result: add(2n, keyCount * add(keyBytes, 1n)),
        work: add(1n, child.work, firstTwice, keyCount * add(keyBytes, 1n)),
        reads: child.reads + (args.length === 1 ? children[0]?.reads ?? 0n : 0n) + keyCount,
        aggregateReads: child.aggregateReads + (args.length === 1 ? children[0]?.aggregateReads ?? 0n : 0n),
      }
    }
    case 'missing_some': {
      const keyBytes = max(children[1]?.result ?? 0n, 1n)
      return base(add(2n, INPUT_NODES * add(keyBytes, 1n)), add(childBytes, INPUT_NODES * add(keyBytes, 1n)), child.reads + INPUT_NODES)
    }
    case '==': case '!=': case '===': case '!==':
      // Object/array equality serializes complete operands in both tiers.
      return base(5n, childBytes)
    case '!': case '!!': case '>': case '>=': case '<': case '<=':
      return base(5n, childBytes)
    case 'and': case 'or': case 'if':
      // A branch short-circuits at runtime; evaluating every executable child is a
      // conservative transfer upper bound, while its result is one selected child/null.
      return base(max(5n, childResult), 0n)
    case '+': case '-': case '*': case '/': case '%': case 'min': case 'max':
      return base(NUMBER_BYTES, childBytes)
    case 'in':
      // Array membership can compare every member; loose equality can serialize both sides.
      return base(5n, INPUT_NODES * add(childBytes, 1n))
    case 'cat': {
      const output = args.length === 0 ? 2n : sum(children.map(item => catStringResultBytes(item.result)))
      // Repeated concatenation copies growing prefixes even where a host uses ropes.
      return base(output, BigInt(args.length) * output)
    }
    case 'agg': {
      const computed = Array.isArray(raw) && raw.length === 3 && raw.every(part => typeof part === 'string')
        ? staticReference?.(cell.agg(raw[1] as string, raw[0] as string, raw[2] as string)) : undefined
      return base(max(aggregateResult, computed ?? 0n), childBytes + 1n, child.reads + 1n, child.aggregateReads + 1n)
    }
    case 'money.add': case 'money.sub': case 'money.mul': {
      // Parse scans the whole captured operand before its 4096-digit refusal; successful
      // decimal alignment/multiply is bounded by the existing 4096 digit/scale contract.
      const count = BigInt(args.length)
      // The evaluator folds every admitted operand. Each add/sub can align against
      // the accumulated mantissa and carry once; every operand is parsed/copy-charged.
      const result = op === 'money.mul' ? MONEY_MUL_RESULT_BYTES : MONEY_DIGITS + MONEY_SCALE + count + 4n
      const decimalWork = childBytes + count * MONEY_DIGITS * MONEY_DIGITS + count * result
      return base(result, decimalWork)
    }
    case 'date.add': return base(12n, childBytes)
    case 'date.diff': return base(NUMBER_BYTES, childBytes)
    case 'date.today': return base(12n, 0n)
    case 'coding.is':
      return base(5n, INPUT_NODES * add(childBytes, 1n))
    default:
      // RuleCompiler.ValidateOperators has already closed the language.  Keeping this
      // refusal here makes a newly added evaluator arm fail proof admission until it has
      // an explicit transfer rule, rather than silently receiving a generic estimate.
      throw new Error(`work proof has no transfer for '${op}'`)
  }
}

/** Derives one executable expression's transfer proof through the shared core-type walker. */
export function deriveCoreWork(node: Json, ruleId: string, dependencyResult = INPUT_BYTES,
  staticReference?: (path: string) => bigint | undefined, aggregateResult = INPUT_BYTES): NodeProof {
  // This call deliberately shares the type derivation's executable/literal boundary.
  deriveCoreTypes(node, ruleId)
  return deriveNode(node, dependencyResult, aggregateResult, staticReference)
}

/**
 * Combines actual admitted rules with finite runtime dimensions.  Dynamic paths are
 * not claimed to be static edges: each resolver lookup and possible cell demand is charged.
 */
export function deriveGraphWork(rules: readonly { source: RuleDefinition, ast: Json, references?: readonly { kind: string }[] }[], limits: RuleEngineLimits): WorkProof {
  // A table admitting no rows still folds to one value (an empty sum is 0): charge at least one fold result.
  const aggregateResult = BigInt(Math.max(1, limits.maxTableRowsPerAggregate)) * MONEY_ADD_RESULT_BYTES
  let dynamicResult = INPUT_BYTES
  let perRule: NodeProof[] = []
  let staticResults = new Map<string, bigint>()
  // Static dependencies are already a checked DAG. Reach a fixed point of this
  // admitted program, rather than using a separately configurable host depth.
  for (let pass = 0; pass <= rules.length; pass++) {
    perRule = rules.map(rule => deriveCoreWork(rule.ast, rule.source.id, INPUT_BYTES,
      path => staticResults.get(path), aggregateResult))
    const next = new Map(staticResults)
    for (let index = 0; index < rules.length; index++) {
      const rule = rules[index]
      if (rule.source.action !== 'Compute') continue
      if (rule.source.scope === 'Field') next.set(`field.${rule.source.scopeTarget}`, perRule[index].result)
      if (rule.source.scope === 'Row') {
        const slash = rule.source.scopeTarget.indexOf('/')
        if (slash >= 0) {
          const key = `row.${rule.source.scopeTarget.slice(slash + 1)}`
          next.set(key, max(next.get(key) ?? 0n, perRule[index].result))
        }
      }
      if (rule.source.scope === 'Table') {
        const [section, fn, col] = rule.source.scopeTarget.split('/')
        const key = cell.agg(section, fn, col)
        next.set(key, max(next.get(key) ?? 0n, perRule[index].result))
      }
    }
    dynamicResult = max(INPUT_BYTES, aggregateResult, ...perRule.map(proof => proof.result))
    const unchanged = next.size === staticResults.size && [...next].every(([key, value]) => staticResults.get(key) === value)
    staticResults = next
    if (unchanged) break
  }

  // Dynamic demand can reach only Compute and aggregate cells. A row Compute may
  // expand to the full graph cap; a field/table Compute and an aggregate reference
  // contribute one cell each. Repeated references only overcount this inventory.
  let potentialCells = 0
  for (const rule of rules) {
    if (rule.source.action === 'Compute') potentialCells += rule.source.scope === 'Row' ? Math.max(0, limits.maxGraphNodes) : 1
    potentialCells += rule.references?.filter(reference => reference.kind === 'agg').length ?? 0
  }
  const demandCellBound = Math.min(Math.max(0, limits.maxGraphNodes), potentialCells)

  // A result-carrying var chain is a statically checked DAG. Dynamic missing
  // reads only test presence and return key names, so they cannot copy a
  // demanded cell's value into this result. The inventory still bounds demand work.
  const hasDynamicRead = rules.some(rule => rule.references?.some(reference => reference.kind === 'dynamic-read'))

  let localWork = 0n
  let resolverReads = 0n
  let aggregateReads = 0n
  let maxCellWork = 1n
  for (let index = 0; index < rules.length; index++) {
    const rule = rules[index]
    const proof = perRule[index]
    const rowExpansion = rule.source.scope === 'Row' ? BigInt(Math.max(0, limits.maxTableRowsPerAggregate)) : 1n
    // Every rule produces an outcome; Compute rules additionally produce a value cell.
    const executions = rowExpansion * (rule.source.action === 'Compute' ? 2n : 1n)
    // Includes outcome/value ownership copies after evaluator execution.
    localWork += executions * add(proof.work, proof.result)
    resolverReads += executions * proof.reads
    aggregateReads += executions * proof.aggregateReads
    if (proof.work > maxCellWork) maxCellWork = proof.work
  }

  if (hasDynamicRead) {
    // A dynamically selected value can be converted, serialized and copied by every
    // executable operand position.  The same finite child factor used for result
    // composition therefore bounds one demanded cell's conversion/copy work.
    const childFactor = 6n * BigInt(Math.max(limits.maxAstNodes, Number(INPUT_NODES)))
    maxCellWork = max(maxCellWork, childFactor * add(dynamicResult, aggregateResult, INPUT_BYTES))
  }

  // Actual dynamic reads can demand a completed graph cell.  The current generation
  // completes each cell once; repeated resolver calls still pay lookup/demand work.
  const dynamicDemand = resolverReads * add(1n, BigInt(demandCellBound) * maxCellWork)
  // Each aggregate fold visits at most the admitted rows and converts/copies a bounded
  // captured row value.  This is separate from the evaluator's agg resolver arm.
  const foldWork = aggregateReads * BigInt(Math.max(0, limits.maxTableRowsPerAggregate))
    * add(max(dynamicResult, aggregateResult, INPUT_BYTES), 1n)
  return Object.freeze({
    maximumResultBytes: dynamicResult,
    maximumEvaluationWork: add(localWork, dynamicDemand, foldWork),
  })
}

src/grammar.ts.source:
/**
 * The neutral compiler's grammar-lowering half (SPINE-1 §1.2) — TS port of
 * `ScopeGrammar`. Lowers the scope-grammar into a canonical normalized AST (`field.` / `row.`
 * vars + the `agg` operator, plus the WF-KEY `wf.` / `timer.` process-context
 * prefixes which pass through canonically). Performed ONCE so both tiers consume
 * the identical normalized AST (the corpus pins `expectedAst`).
 */
import { Codes } from './codes.js'
import type { Json, OutputType, RuleActionKind, RuleScope } from './model.js'
import type { RuleEngineLimits } from './limits.js'
import { aggregateFolds } from './jsonlogic.js'

export interface LowerContext {
  scope: RuleScope
  scopeTarget: string
  sectionId: string | null
}

export type RuleRef =
  | { kind: 'field'; name: string }
  | { kind: 'dynamic-read' }
  | { kind: 'row'; field: string }
  | { kind: 'agg'; section: string; fn: string; col: string }

export class CompileError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly ruleId?: string,
    readonly cyclePath?: string[],
    /** Stable string params (for `rule.compile.work_exceeded`: `proof` and `ceiling`). */
    readonly params: Readonly<Record<string, string>> = {},
  ) {
    super(message)
  }
}

export function outputTypeFor(action: RuleActionKind): OutputType {
  switch (action) {
    case 'Compute': return 'Value'
    case 'Validate': return 'Validity'
    case 'Presentation': return 'Presentation'
    case 'Options': return 'Options'
    default: return 'Visibility' // Visibility | Required | ReadOnly
  }
}

function isObj(n: Json): n is { [k: string]: Json } {
  return typeof n === 'object' && n !== null && !Array.isArray(n)
}

export function lower(expression: string | Json, ctx: LowerContext, ruleId: string): Json {
  let parsed: Json
  if (typeof expression === 'string') {
    try {
      parsed = JSON.parse(expression)
    } catch (e) {
      throw new CompileError(Codes.compileInvalidExpression,
        `rule '${ruleId}': expression is not valid JSON: ${(e as Error).message}`, ruleId)
    }
  } else {
    parsed = expression
  }
  return rewrite(parsed, ctx, ruleId)
}

function rewrite(node: Json, ctx: LowerContext, ruleId: string): Json {
  if (isObj(node) && Object.keys(node).length === 1 && 'var' in node) {
    const pathNode = node['var']
    const path = Array.isArray(pathNode) ? pathNode[0] : pathNode
    const def = Array.isArray(pathNode) ? pathNode[1] : undefined
    // rules-ck-7 addresses named cells with static strings lowered here, once. A numeric
    // (array-index), computed, null or empty operand has no canonical cell, and lowering it
    // to field '' reads the wrong value and hides a dynamic read from the work proof.
    if (typeof path !== 'string' || path.length === 0) {
      throw bad(ruleId, 'a var path must be a non-empty string from the scope-addressing grammar')
    }
    if (path.startsWith('table.') && path.includes('(')) {
      return lowerAgg(path, ctx, ruleId)
    }
    const canonical = lowerVarPath(path, ctx, ruleId)
    return def !== undefined ? { var: [canonical, rewrite(def, ctx, ruleId)] } : { var: canonical }
  }
  if (isObj(node)) {
    const entries = Object.entries(node)
    if (entries.length !== 1) return cloneJson(node)
    const [key, value] = entries[0]
    return { [key]: Array.isArray(value) ? value.map((item) => rewrite(item, ctx, ruleId)) : rewrite(value, ctx, ruleId) }
  }
  if (Array.isArray(node)) return cloneJson(node)
  return node
}

function cloneJson(node: Json): Json {
  if (Array.isArray(node)) return node.map(cloneJson)
  if (isObj(node)) return Object.fromEntries(Object.entries(node).map(([key, value]) => [key, cloneJson(value)]))
  return node
}

function lowerAgg(path: string, ctx: LowerContext, ruleId: string): Json {
  const open = path.indexOf('(')
  const close = path.indexOf(')')
  if (close <= open) throw bad(ruleId, `malformed table aggregate '${path}'`)
  const fn = path.slice(6, open)
  const arg = path.slice(open + 1, close)
  let section: string
  let col: string
  const dot = arg.indexOf('.')
  if (dot >= 0) {
    section = arg.slice(0, dot)
    col = arg.slice(dot + 1)
  } else {
    if (ctx.sectionId === null) {
      throw bad(ruleId, `table aggregate '${path}' needs an explicit section (table.${fn}(section.${arg})) outside a row/table-scoped rule`)
    }
    section = ctx.sectionId
    col = arg
  }
  if (fn.length === 0 || section.length === 0 || col.length === 0) throw bad(ruleId, `malformed table aggregate '${path}'`)
  return { agg: [fn, section, col] }
}

// Scope roots a borrower may declare (Forms forms-ck-13, Documents documents-ck-25) that no R1
// evaluator supplies. Lowering them as bare field names let a rule read a client-supplied candidate
// property in place of the authenticated principal, the evaluation instant or the record type, so the
// compiler refuses them (fail closed) until an evaluator binds them; mirrors the .NET ScopeGrammar.
// A record field of the same name stays addressable as field.<name>.
const unsuppliedRoots: ReadonlySet<string> = new Set(['caller', 'clock', 'record_type'])

function refuseUnsuppliedRoot(path: string, ruleId: string): void {
  const dot = path.indexOf('.')
  if (unsuppliedRoots.has(dot < 0 ? path : path.slice(0, dot))) {
    throw bad(ruleId, `'${path}' addresses a scope root no evaluator supplies; use field.${path} for a record field`)
  }
}

function lowerVarPath(path: string, ctx: LowerContext, ruleId: string): string {
  refuseUnsuppliedRoot(path, ruleId)
  if (path === 'self') {
    if (ctx.scope === 'Row') return 'row.' + rowFieldOf(ctx, ruleId)
    if (ctx.scope === 'Field') return 'field.' + ctx.scopeTarget
    throw bad(ruleId, "'self' is only valid in a Field- or Row-scoped rule")
  }
  if (path.startsWith('row.')) {
    if (ctx.scope !== 'Row') throw bad(ruleId, `'row.' reference '${path}' is only valid in a Row-scoped rule`)
    return path
  }
  if (path.startsWith('parent.')) return 'field.' + path.slice('parent.'.length)
  if (path.startsWith('field.')) return path
  if (path.startsWith('section.')) {
    const rest = path.slice('section.'.length)
    const firstDot = rest.indexOf('.')
    if (firstDot < 0) throw bad(ruleId, `malformed section reference '${path}' (expected section.<id>.<field>)`)
    return 'field.' + rest.slice(firstDot + 1)
  }
  // WF-KEY (ADR 0140) process-context prefixes: wf.state / wf.actor / wf.iteration /
  // timer.<id>. A workflow guard reads the PROCESS context bag, not a record cell, so
  // these pass through CANONICALLY (no `field.` rewrite) and are NOT extracted as field
  // deps (see `extractRefs` below — only field./row./agg participate in the form graph).
  // Additive: no form rule addresses a `wf.`/`timer.`-prefixed cell, so existing lowering
  // is byte-identical. The contract that authors these is @harborline-software/contracts WorkflowDefinition.
  // T-741: `candidate.` is a third declared context prefix, mirrored from the .NET tier's
  // ScopeGrammar so Rules' borrower-admission check (DES-0018 rules-ck-28) can refuse an
  // undeclared reference on both tiers rather than only where it happens to run first.
  if (path.startsWith('wf.') || path.startsWith('timer.') || path.startsWith('candidate.')) {
    return path
  }
  return 'field.' + path
}

function rowFieldOf(ctx: LowerContext, ruleId: string): string {
  const slash = ctx.scopeTarget.indexOf('/')
  if (slash < 0) throw bad(ruleId, `Row rule ScopeTarget '${ctx.scopeTarget}' must be 'section/field'`)
  return ctx.scopeTarget.slice(slash + 1)
}

function bad(ruleId: string, message: string): CompileError {
  return new CompileError(Codes.compileBadGrammar, `rule '${ruleId}': ${message}`, ruleId)
}

// ── reference extraction ────────────────────────────────────────────────────

export function extractRefs(ast: Json, ruleId = ''): RuleRef[] {
  const refs: RuleRef[] = []
  walk(ast, refs, ruleId)
  return refs
}

function walk(node: Json, refs: RuleRef[], ruleId: string): void {
  if (isObj(node) && Object.keys(node).length === 1 && ('missing' in node || 'missing_some' in node)) {
    const raw = Object.values(node)[0]
    const args = Array.isArray(raw) ? raw : [raw]
    if ('missing_some' in node) {
      if (args.length > 0) walk(args[0], refs, ruleId)
      if (args.length > 1) collectMissingKeys(args[1], refs, ruleId)
    } else for (const arg of args) collectMissingKeys(arg, refs, ruleId)
    return
  }
  if (isObj(node) && Object.keys(node).length === 1 && 'var' in node) {
    const path = varPathOf(node['var'])
    if (path.startsWith('field.')) refs.push({ kind: 'field', name: path.slice('field.'.length) })
    else if (path.startsWith('row.')) refs.push({ kind: 'row', field: path.slice('row.'.length) })
    if (Array.isArray(node['var']) && node['var'].length > 1) walk(node['var'][1], refs, ruleId)
    return
  }
  if (isObj(node) && Object.keys(node).length === 1 && 'agg' in node) {
    const a = node['agg']
    // Ticket 162 review (150-family direction): an agg node the graph cannot statically
    // register — wrong arity, or expression-valued/non-string args — used to be SKIPPED here,
    // leaving no fold cell. It then refused per-keystroke at runtime with no authoring-time
    // signal (and a dynamic arg registered a phantom String()-coerced cell). The compiler
    // refuses it instead: publish rejects it with a stable code; nothing un-saveable ships.
    if (!Array.isArray(a) || a.length !== 3 || a.some((part) => typeof part !== 'string')) {
      throw new CompileError(Codes.compileBadGrammar,
        `rule '${ruleId}': a table aggregate must be a static [fn, section, col] string triple`, ruleId)
    }
    // rules-eng-16: a fold is one of the register's bounded folds over a named child collection;
    // anything else (a search, a query, a catalogue measure) is not a fold.
    if (!(aggregateFolds as readonly string[]).includes(a[0] as string)) {
      throw new CompileError(Codes.compileBadGrammar, `rule '${ruleId}': '${a[0] as string}' is not a registered bounded fold`, ruleId)
    }
    refs.push({ kind: 'agg', fn: a[0] as string, section: a[1] as string, col: a[2] as string })
    return
  }
  if (isObj(node) && Object.keys(node).length === 1) {
    const argument = Object.values(node)[0]
    if (Array.isArray(argument)) {
      for (const item of argument) walk(item, refs, ruleId)
    } else {
      walk(argument, refs, ruleId)
    }
  }
}

function collectMissingKeys(value: Json, refs: RuleRef[], ruleId: string): void {
  if (Array.isArray(value)) { for (const item of value) collectMissingKeys(item, refs, ruleId); return }
  if (typeof value === 'string' && value.length > 0) {
    refuseUnsuppliedRoot(value, ruleId)
    if (value.startsWith('row.')) refs.push({ kind: 'row', field: value.slice('row.'.length) })
    else refs.push({ kind: 'field', name: value.startsWith('field.') ? value.slice('field.'.length) : value })
    return
  }
  if (isObj(value) && Object.keys(value).length === 1) {
    walk(value, refs, ruleId)
    refs.push({ kind: 'dynamic-read' })
    return
  }
  refs.push({ kind: 'dynamic-read' })
}

function varPathOf(varNode: Json): string {
  if (Array.isArray(varNode)) return varNode.length > 0 ? String(varNode[0]) : ''
  return typeof varNode === 'string' ? varNode : ''
}

// ── AST metrics (static bounds) ─────────────────────────────────────────────

export function measure(node: Json, limits: RuleEngineLimits, ruleId: string): number {
  let count = 1
  if (isObj(node)) {
    for (const v of Object.values(node)) count += measure(v, limits, ruleId)
  } else if (Array.isArray(node)) {
    for (const item of node) count += measure(item, limits, ruleId)
  } else if (typeof node === 'string' && node.length > limits.maxLiteralLength) {
    throw new CompileError(Codes.compileLiteralTooLong,
      `rule '${ruleId}': a string literal of length ${node.length} exceeds the bound ${limits.maxLiteralLength}`, ruleId)
  }
  return count
}

